sub strip_name{
local($_) = @_;
s/^([A-Z][-a-z]+) (X?[-a-z]+).*(subsp\.|ssp\.|var\.|f\.) ([-a-z]+).*/$1 $2 $3 $4/ ||
s/^([A-Z][a-z]+) ([xX ]*[-a-z]+).*/$1 $2/;
s/ssp\./subsp./;
return ($_);
}

sub print_tag {
#print "<tr><th valign=top align=right><a href=\"/cgi-bin/get_cpn.pl?help=$help_word\">$_</td></tr>\n";
($leader,$line)=@_;
($help_word=$leader)=~s/ /+/g;
$help_word=~s/\+[0-9a-z]$//;
$leader="<a href=\"/cgi-bin/get_cpn.pl?help=$help_word\">$leader</a>"
unless $leader=~/^[a-z0-9]$/;
#$line=~s/Å½/&eacute;/g;
return<<EOR;
<tr>
<th valign="top" align="right" width="25%">
$leader
</th>
<td valign="top" width="75%">
$line
</td>
</tr>
EOR
}

